// One card, two things, told apart by a flag: a hook can read one, and cannot read a mark.
if (!ctx.flag('the-page')) {
  ctx.log('The place is kept.', 'system');
  ctx.queue([{ kind: 'markSpot', mark: 'the-page' }, { kind: 'setFlag', flag: 'the-page' }]);
  return true;
}
ctx.log('Back to the place that was kept.', 'system');
ctx.queue([
  { kind: 'move', to: 'mark', mark: 'the-page', teleport: true },
  { kind: 'forgetSpot', mark: 'the-page' },
  { kind: 'clearFlag', flag: 'the-page' },
]);
return true;

// ctx.select takes the same selectors content writes.
var allies = ctx.select({ kind: 'allies', range: 'close', includeSelf: true });
if (allies.length === 0) {
  ctx.log('Nobody stands close enough to rally.', 'system');
  return false;
}
var effects = [];
for (var i = 0; i < allies.length; i++) {
  var id = allies[i];
  var marked = ctx.pool(id, 'hitPoints', 'marked') || 0;
  var max = ctx.pool(id, 'hitPoints', 'max') || 1;
  var who = { kind: 'entity', id: id };
  // More than half their Hit Points marked: the wound is the urgent thing.
  effects.push(marked * 2 > max
    ? { kind: 'heal', amount: 1, target: who }
    : { kind: 'clearStress', amount: 1, target: who });
}
ctx.log('The line steadies.', 'good');
ctx.queue(effects);
return true;

var actor = ctx.actor;
var target = ctx.targets[0];
if (actor === null || target === undefined) return;
var good = ctx.pool(actor, 'good') || 0;
if (good < 1) {
  ctx.log('No Light to spend: the projectiles never form.', 'system');
  return;
}
var options = [];
for (var spent = 1; spent <= good; spent++) {
  options.push({
    label: spent + ' Light: ' + spent + 'd6 magic',
    effects: [
      { kind: 'spendGood', amount: spent },
      { kind: 'damage', dice: spent + 'd6', type: 'magic', target: { kind: 'target' } }
    ]
  });
}
ctx.queue([{ kind: 'choice', title: 'Arcane Barrage', body: 'How much Light goes into it?', options: options }]);

var actor = ctx.actor;
if (actor === null) return;
var free = ctx.pool(actor, 'stress', 'available') || 0;
if (free < 1) {
  ctx.log('No Stress left to spend: the sky holds.', 'system');
  return;
}
var options = [];
for (var spent = 1; spent <= free; spent++) {
  options.push({
    label: spent + ' Stress: ' + spent + 'd20+' + (spent * 2) + ' magic',
    effects: [
      { kind: 'markStress', amount: spent, target: { kind: 'actor' } },
      {
        kind: 'check',
        check: {
          trait: 'spellcast',
          difficulty: 'target',
          targets: { kind: 'adversaries', range: 'far' },
          onSuccessWithGood: [{ kind: 'damage', dice: spent + 'd20+' + (spent * 2), type: 'magic' }]
        }
      }
    ]
  });
}
ctx.queue([{ kind: 'choice', title: 'Falling Sky', body: 'How much of yourself goes into it?', options: options }]);

var reached = ctx.select({ kind: 'adversaries', range: 'melee' }).slice(0, 3);
if (reached.length === 0) {
  ctx.log('Nothing stands close enough to burn.', 'system');
  return;
}
ctx.queue([{
  kind: 'check',
  check: {
    trait: 'spellcast',
    difficulty: 'target',
    targets: { kind: 'entities', ids: reached },
    onSuccessWithGood: [
      { kind: 'damage', dice: '2d6', type: 'magic' },
      { kind: 'markStress', target: { kind: 'hit' } }
    ]
  }
}]);

